import { apiSecurityHeaders } from "../../config/security";

/** Static asset _headers rules do not cover responses generated by a Worker. */
export function withApiSecurityHeaders(response: Response): Response {
  const headers = new Headers(response.headers);
  for (const [name, value] of Object.entries(apiSecurityHeaders)) {
    headers.set(name, value);
  }
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers
  });
}
